peMap["kids"] = "kids";productTypeMap["knob"] = "knob";productTypeMap["knurled nut"] = "knurled-nut";productTypeMap["koozie"] = "koozie";productTypeMap["license plate"] = "license-plate";I18n.productTypeMap = productTypeMap;

