      window.Globo.FormBuilder.forms[104232] = {"104232":{"elements":[{"id":"group-1","type":"group","label":"Page 1","description":"","elements":[{"id":"paragraph-1","type":"paragraph","text":{"en":"<p>This year, <strong>Gibson proudly celebrates 50 years in Nashville</strong>, and we're kicking off the celebration honoring the heart of our brand - <strong>the people behind the music</strong>. In support of our new Gibson.com site, we're launching "<strong>50 Years in Music City</strong>," a digital campaign featuring our Team Members with Gibson guitars and gear in the iconic places and spaces across Nashville.</p><p><br></p><p><strong><u>Want to be featured? Here's how to participate:</u></strong></p><p><br></p><p>• Submit a photo of yourself with a Gibson guitar or piece of gear, taken somewhere in or around Nashville</p><p><br></p><p>Along with your photo, include:</p><p><br></p><p>• The location (e.g. hanging in the Gibson Garage, playing a gig on Broadway, posing by a mural downtown, recording in a studio in Germantown, jamming in East Nashville, etc.)</p><p><br></p><p>• A short description or story behind the photo</p><p><br></p><p>• The model of the guitar or details of the gear</p><p><br></p><p>• Your Instagram or social handle (optional, if you'd like us to tag you)</p><p><br></p><p>Selected submissions will be featured as part of an interactive experience on our new site and/or social media platforms - a tribute to the people, stories and sounds that define Gibson.</p><p><br></p><p>Join us in celebrating five decades in Music City - and be part of the story.</p>","de":"<p>This year, <strong>Gibson proudly celebrates 50 years in Nashville</strong>, and we're kicking off the celebration honoring the heart of our brand - <strong>the people behind the music</strong>. In support of our new Gibson.com site, we're launching "<strong>50 Years in Music City</strong>," a digital campaign featuring our Team Members with Gibson guitars and gear in the iconic places and spaces across Nashville.</p><p><br></p><p><strong><u>Want to be featured? Here's how to participate:</u></strong></p><p><br></p><p>• Submit a photo of yourself with a Gibson guitar or piece of gear, taken somewhere in or around Nashville</p><p><br></p><p>Along with your photo, include:</p><p><br></p><p>• The location (e.g. hanging in the Gibson Garage, playing a gig on Broadway, posing by a mural downtown, recording in a studio in Germantown, jamming in East Nashville, etc.)</p><p><br></p><p>• A short description or story behind the photo</p><p><br></p><p>• The model of the guitar or details of the gear</p><p><br></p><p>• Your Instagram or social handle (optional, if you'd like us to tag you)</p><p><br></p><p>Selected submissions will be featured as part of an interactive experience on our new site and/or social media platforms - a tribute to the people, stories and sounds that define Gibson.</p><p><br></p><p>Join us in celebrating five decades in Music City - and be part of the story.</p>","es":"<p>This year, <strong>Gibson proudly celebrates 50 years in Nashville</strong>, and we're kicking off the celebration honoring the heart of our brand - <strong>the people behind the music</strong>. In support of our new Gibson.com site, we're launching "<strong>50 Years in Music City</strong>," a digital campaign featuring our Team Members with Gibson guitars and gear in the iconic places and spaces across Nashville.</p><p><br></p><p><strong><u>Want to be featured? Here's how to participate:</u></strong></p><p><br></p><p>• Submit a photo of yourself with a Gibson guitar or piece of gear, taken somewhere in or around Nashville</p><p><br></p><p>Along with your photo, include:</p><p><br></p><p>• The location (e.g. hanging in the Gibson Garage, playing a gig on Broadway, posing by a mural downtown, recording in a studio in Germantown, jamming in East Nashville, etc.)</p><p><br></p><p>• A short description or story behind the photo</p><p><br></p><p>• The model of the guitar or details of the gear</p><p><br></p><p>• Your Instagram or social handle (optional, if you'd like us to tag you)</p><p><br></p><p>Selected submissions will be featured as part of an interactive experience on our new site and/or social media platforms - a tribute to the people, stories and sounds that define Gibson.</p><p><br></p><p>Join us in celebrating five decades in Music City - and be part of the story.</p>","fr":"<p>This year, <strong>Gibson proudly celebrates 50 years in Nashville</strong>, and we're kicking off the celebration honoring the heart of our brand - <strong>the people behind the music</strong>. In support of our new Gibson.com site, we're launching "<strong>50 Years in Music City</strong>," a digital campaign featuring our Team Members with Gibson guitars and gear in the iconic places and spaces across Nashville.</p><p><br></p><p><strong><u>Want to be featured? Here's how to participate:</u></strong></p><p><br></p><p>• Submit a photo of yourself with a Gibson guitar or piece of gear, taken somewhere in or around Nashville</p><p><br></p><p>Along with your photo, include:</p><p><br></p><p>• The location (e.g. hanging in the Gibson Garage, playing a gig on Broadway, posing by a mural downtown, recording in a studio in Germantown, jamming in East Nashville, etc.)</p><p><br></p><p>• A short description or story behind the photo</p><p><br></p><p>• The model of the guitar or details of the gear</p><p><br></p><p>• Your Instagram or social handle (optional, if you'd like us to tag you)</p><p><br></p><p>Selected submissions will be featured as part of an interactive experience on our new site and/or social media platforms - a tribute to the people, stories and sounds that define Gibson.</p><p><br></p><p>Join us in celebrating five decades in Music City - and be part of the story.</p>","it":"<p>This year, <strong>Gibson proudly celebrates 50 years in Nashville</strong>, and we're kicking off the celebration honoring the heart of our brand - <strong>the people behind the music</strong>. In support of our new Gibson.com site, we're launching "<strong>50 Years in Music City</strong>," a digital campaign featuring our Team Members with Gibson guitars and gear in the iconic places and spaces across Nashville.</p><p><br></p><p><strong><u>Want to be featured? Here's how to participate:</u></strong></p><p><br></p><p>• Submit a photo of yourself with a Gibson guitar or piece of gear, taken somewhere in or around Nashville</p><p><br></p><p>Along with your photo, include:</p><p><br></p><p>• The location (e.g. hanging in the Gibson Garage, playing a gig on Broadway, posing by a mural downtown, recording in a studio in Germantown, jamming in East Nashville, etc.)</p><p><br></p><p>• A short description or story behind the photo</p><p><br></p><p>• The model of the guitar or details of the gear</p><p><br></p><p>• Your Instagram or social handle (optional, if you'd like us to tag you)</p><p><br></p><p>Selected submissions will be featured as part of an interactive experience on our new site and/or social media platforms - a tribute to the people, stories and sounds that define Gibson.</p><p><br></p><p>Join us in celebrating five decades in Music City - and be part of the story.</p>","nl":"<p>This year, <strong>Gibson proudly celebrates 50 years in Nashville</strong>, and we're kicking off the celebration honoring the heart of our brand - <strong>the people behind the music</strong>. In support of our new Gibson.com site, we're launching "<strong>50 Years in Music City</strong>," a digital campaign featuring our Team Members with Gibson guitars and gear in the iconic places and spaces across Nashville.</p><p><br></p><p><strong><u>Want to be featured? Here's how to participate:</u></strong></p><p><br></p><p>• Submit a photo of yourself with a Gibson guitar or piece of gear, taken somewhere in or around Nashville</p><p><br></p><p>Along with your photo, include:</p><p><br></p><p>• The location (e.g. hanging in the Gibson Garage, playing a gig on Broadway, posing by a mural downtown, recording in a studio in Germantown, jamming in East Nashville, etc.)</p><p><br></p><p>• A short description or story behind the photo</p><p><br></p><p>• The model of the guitar or details of the gear</p><p><br></p><p>• Your Instagram or social handle (optional, if you'd like us to tag you)</p><p><br></p><p>Selected submissions will be featured as part of an interactive experience on our new site and/or social media platforms - a tribute to the people, stories and sounds that define Gibson.</p><p><br></p><p>Join us in celebrating five decades in Music City - and be part of the story.</p>"},"columnWidth":100,"displayType":"show","displayDisjunctive":false},{"id":"html-1","type":"html","html":{"en":"<style>
