document.addEventListener('DOMContentLoaded', function () {
  function setMixpanelDistinctId(field) {
    if (!field) return;

    try {
      var mixpanelId =
        (window.mixpanel &&
          typeof window.mixpanel.get_distinct_id === 'function' &&
          window.mixpanel.get_distinct_id()) ||
        window.__mixpanelDistinctId ||
        field.value;

      if (mixpanelId) {
        field.value = mixpanelId;
      }
    } catch (e) {
      console.error('Error setting Mixpanel distinct id on cart drawer:', e);
    }
  }

  function initializeMixpanelField() {
    var field = document.getElementById('mixpanel_distinct_id');
    if (!field) return;

    if (window.__mixpanelDistinctId || (window.mixpanel && typeof window.mixpanel.get_distinct_id === 'function')) {
      setMixpanelDistinctId(field);
    } else {
      setTimeout(initializeMixpanelField, 200);
    }
  }

  // Ensure the attribute is set even when checking out with an existing cart
  document.addEventListener('submit', function (event) {
    var form = event.target;
    if (!form || form.id !== 'CartDrawer-Form') return;

    var field = document.getElementById('mixpanel_distinct_id');
    if (!field) return;

    setMixpanelDistinctId(field);
  });

  initializeMixpanelField();
});

