  js.onload = function () {
    function start() {
      try {
        nv_shopnow.init();
      } catch (e) {
        // Widget failing to initialise must not break the page.
      }
    }
    // init() scans the DOM, so it must not run before parsing finishes. A
    // dynamically inserted script is always async — `defer` on it is ignored.
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', start);
    } else {
      start();
    }
  };
  document.head.appendChild(js);
});

(function() {
  // Utility to check if referrer is from shopify.com
  function isReferrerFromShopify() {
    console.log(document.referrer);
    return document.referrer.includes('account.gibson.com');
  }
  // Utility to check if customer object is present (customize as needed)
  function isCustomerMissing() {
    // You might check for a global object, session, or localStorage
    return '';
  }
  // Function to "hit a SLO" — customize this to your logging/metrics service
  function hitSLO() {
    const slo_url = `https://identity.gibson.com/houseofstathopoulo.onmicrosoft.com/B2C_1_Gibson_Sign_On/oauth2/v2.0/logout?post_logout_redirect_uri=https://shopify.com/65939669171/account/logout_callback`;
    window.location.href = slo_url;
  }
  // Main logic
  if (isReferrerFromShopify() && isCustomerMissing() == "") {
    hitSLO();
  }
})();

