  function storefrontGraphql(query, variables) {
    const cfg = window._RestockRocketConfig;
    if (!cfg.storefrontAccessToken || cfg.disableStorefrontApi === true) {
      return Promise.reject(new Error('Storefront API unavailable'));
    }
    return fetch(
      `https://${cfg.shop}/api/${cfg.storefrontApiVersion}/graphql.json`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Storefront-Access-Token': cfg.storefrontAccessToken,
        },
        body: JSON.stringify({ query: query, variables: variables }),
      }
    )
    .then(function(response) {
      if (!response.ok) { throw new Error('Storefront API HTTP ' + response.status); }
      return response.json();
    })
    .then(function(body) {
      if (body && body.errors && body.errors.length) {
        throw new Error('Storefront API errors: ' + body.errors.map(function(e) { return e && e.message; }).join(', '));
      }
      return body && body.data;
    });
  }
  function fetchStorefrontShopMetafield(key) {
    const cfg = window._RestockRocketConfig;
    const query = 'query StoqShopMetafield($namespace: String!, $key: String!) { shop { metafield(namespace: $namespace, key: $key) { value } } }';
    return storefrontGraphql(query, { namespace: cfg.metafieldNamespace, key: key })
    .then(function(data) {
      const value = data && data.shop && data.shop.metafield && data.shop.metafield.value;
      if (!value) { throw new Error('Storefront API returned no ' + key + ' metafield value'); }
      return JSON.parse(value);
    });
  }
  (function loadStorefrontSettings() {
    const cfg = window._RestockRocketConfig;
    if (!cfg.storefrontAccessToken || cfg.disableStorefrontApi === true) return;
    function run() {
      // The live-settings read is one more shop-level metafield fetch, so it
      // shares fetchStorefrontShopMetafield with the integrations/selling_plans
      // reads rather than re-issuing the same query + parse.
      fetchStorefrontShopMetafield('settings')
      .then(function(settings) {
        cfg.storefrontSettings = settings;
        console.debug('STOQ - stored live settings from Storefront API on config.storefrontSettings');
      })
      .catch(function(e) {
        console.debug('STOQ - Storefront settings fetch failed (non-fatal):', e && e.message);
      });
    }

    if (typeof window.requestIdleCallback === 'function') {
      window.requestIdleCallback(run, { timeout: 5000 });
    } else {
      setTimeout(run, 0);
    }
  })();
  const cachedSettings = window._RestockRocketConfig.cachedSettings;
  const validCachedSettings = cachedSettings ? checkSettingsExpiry(cachedSettings) : null;

  if (validCachedSettings) {
    console.debug('STOQ - using cached settings');
    initializeScripts(validCachedSettings);
  } else {
    console.debug('STOQ - fetching fresh settings');
    const headers = {
      'X-Shopify-Shop-Domain': window._RestockRocketConfig.shop || window.Shopify.shop,
      'ngrok-skip-browser-warning': 'skip'
    };

    if (window.Shopify?.theme?.role === 'main') {
      headers['X-Shopify-Theme-Schema-Name'] = window.Shopify.theme.schema_name;
      headers['X-Shopify-Theme-Schema-Version'] = window.Shopify.theme.schema_version;
      headers['X-Shopify-Theme-Store-Id'] = window.Shopify.theme.theme_store_id;
    }

    fetch(
      `${window._RestockRocketConfig.host}/api/v1/setting.json?translation_locale=${window._RestockRocketConfig.normalizedLocale}`,
      { headers }
    )
    .then(function(response) {
      if (!response.ok) {
        throw new Error('Network response was not ok');
      }
      return response.json();
    })
    .then(function(settings) {
      initializeScripts(settings);
    })
    .catch(function(error) {
      if (cachedSettings) {
        console.debug('STOQ - using expired cached settings as fallback');
        initializeScripts(cachedSettings);
      } else {
        console.error('STOQ - failed to load settings:', error);
      }
    })
    .catch(function(e) {
      console.error(e)
    })
  }

  function fetchEmbedConfig(endpoint, apply) {
    return fetch(
      `${window._RestockRocketConfig.host}/api/v1/embed/${endpoint}.json`,
      {
        headers: {
          'X-Shopify-Shop-Domain': window._RestockRocketConfig.shop || window.Shopify.shop,
          'ngrok-skip-browser-warning': 'skip'
        }
      }
    )
    .then(function(response) {
      if (!response.ok) throw new Error(`Failed to fetch ${endpoint}`);
      return response.json();
    })
    .then(function(data) {
      try {
        apply(data);
      } catch (applyError) {
        console.error('STOQ - apply failed for ' + endpoint + ':', applyError);
        throw applyError;
      }
    })
    .catch(function(error) {
      console.debug(`STOQ - using cached ${endpoint}:`, error.message);
    });
  }
  function refreshShopConfig(source) {
    const cfg = window._RestockRocketConfig;
    const viaEmbed = function() { return fetchEmbedConfig(source.endpoint, source.apply); };
    const flagOn = !!cfg.readFlags && cfg.readFlags[source.flag] === true;
    if (!flagOn || source.embedOnly === true) { return viaEmbed(); }

    return fetchStorefrontShopMetafield(source.metafieldKey)
      .then(function(value) {
        if (!source.isValid(value)) { throw new Error(source.metafieldKey + ' metafield is not a valid ' + source.endpoint + ' payload'); }
        source.apply(value);
        console.debug('STOQ - refreshed ' + source.endpoint + ' from the Storefront API');
      })
      .catch(function(error) {
        console.debug('STOQ - Storefront ' + source.endpoint + ' read failed, using embed:', error.message);
        return viaEmbed();
      });
  }
  function refreshIntegrations() {
    const cfg = window._RestockRocketConfig;
    return refreshShopConfig({
      endpoint: 'integrations',
      metafieldKey: 'integrations',
      flag: 'enable_storefront_integrations_read',
      isValid: function(value) { return Array.isArray(value); },
      apply: function(data) {
        cfg.integrations = data;
      }
    });
  }
  function refreshSellingPlans(embedOnly) {
    const cfg = window._RestockRocketConfig;
    return refreshShopConfig({
      embedOnly: embedOnly === true,
      endpoint: 'selling_plans',
      metafieldKey: 'cachedSellingPlans',
      flag: 'enable_storefront_selling_plans_read',
      isValid: function(value) { return !!value && Array.isArray(value.plans); },
      apply: function(data) {
        cfg.sellingPlans = data.plans;
        cfg.disabledSellingPlanIds = data.disabled_plan_ids || [];
        if (data && data.read_flags && typeof data.read_flags === 'object' && !Array.isArray(data.read_flags)) {
          cfg.readFlags = data.read_flags;
        }
      }
    });
  }

  function initializeScripts(settings) {
    settings = applyTranslations(settings);
    window._RestockRocketConfig.settings = settings;
    console.debug(`STOQ - settings configured for ${window._RestockRocketConfig.pageType}`);
    const forceEmbedSellingPlans = settings.force_embed_selling_plans === true;
    const staleRefresh = !window._RestockRocketConfig.isLiquidCacheFresh && !settings.disable_refresh_on_stale_liquid;
    if (forceEmbedSellingPlans || staleRefresh) {
      console.debug('STOQ - refreshing selling_plans' + (staleRefresh ? ' + integrations (Liquid cache stale)' : ' (force_embed_selling_plans)'));
      const refreshes = [refreshSellingPlans(forceEmbedSellingPlans)];
      if (staleRefresh) { refreshes.push(refreshIntegrations()); }
      Promise.race([
        Promise.all(refreshes),
        new Promise(function(resolve) { setTimeout(resolve, 1000); })
      ]).then(function() { loadScripts(settings); });
      return;
    }

    loadScripts(settings);
  }

  function loadScripts(settings) {
    setupCartSellingPlanUpdater(settings);

    if(settings.enable_app) {
      const hijackIntegration = window._RestockRocketConfig.integrations.find(function(integration) {
        return integration.type === 'hijack' && integration.enabled && integration.page_types.includes(window._RestockRocketConfig.pageType);
      })
      const hasEnabledOffer = Array.isArray(window._RestockRocketConfig.sellingPlans)
        && window._RestockRocketConfig.sellingPlans.some(function(plan) { return plan && plan.enabled; });
      const hasDisabledPlanIds = Array.isArray(window._RestockRocketConfig.disabledSellingPlanIds)
        && window._RestockRocketConfig.disabledSellingPlanIds.length > 0;
      const usePreorderBuild = settings.preorder_enabled || hasEnabledOffer || hasDisabledPlanIds;

      const collectionScriptUrl = usePreorderBuild
        ? window._RestockRocketConfig.scriptUrlCollection
        : window._RestockRocketConfig.scriptUrlCollectionBis;
      const productScriptUrl = usePreorderBuild
        ? window._RestockRocketConfig.scriptUrlProduct
        : window._RestockRocketConfig.scriptUrlProductBis;

      const pageType = window._RestockRocketConfig.pageType;
      const collectionPageTypes = ['collection', 'index', 'search', 'page'];

      if(collectionPageTypes.indexOf(pageType) !== -1 && (settings[`show_button_on_${pageType}`] || settings[`preorder_${pageType}_enabled`])) {
        createRestockRocketScript(collectionScriptUrl);
      } else if(pageType === 'product') {
        createRestockRocketScript(productScriptUrl);
      } else if(hijackIntegration) {
        createRestockRocketScript(window._RestockRocketConfig.scriptUrlCollection);
      } else if(usePreorderBuild) {
        createRestockRocketScript(window._RestockRocketConfig.scriptUrlCollection);
      } else {
        console.debug(`STOQ - no scripts enabled for ${pageType}`);
      }
      const appLoadedEvent = new CustomEvent('stoq:loaded', {
        detail: {
          pageType: window._RestockRocketConfig.pageType,
          enabled: settings.enable_app,
          settings: settings,
          preorderEnabled: settings.preorder_enabled
        }
      });
      console.debug('STOQ - dispatching app loaded event');
      window.dispatchEvent(appLoadedEvent);
    }
  }
